function applyWaalaxyResult(cand, wx, res, nowMs) {
  const now = new Date(nowMs).toISOString();
  const st = cand.channel_state || {};
  const prev = st.linkedin || {};
  const httpOk = res && Number(res.statusCode || 200) < 300;
  const item = httpOk && res.body && Array.isArray(res.body.result) ? res.body.result[0] : null;
  const importCode = item ? item.importCode : null, campCode = item ? item.addToCampaignCode || null : null;
  const pid = item && item.prospect && item.prospect._id ? String(item.prospect._id) : null;
  const events = (prev.events || []).slice(-19);
  let state, ok = false, next, note, msg;
  if (!httpOk || !item) {
    const code = res && res.body && (res.body.code || res.body.title || res.body.message);
    const hint = ({ 'M000401-001': 'La cuenta de Waalaxy no tiene permisos para esta operación (¿plan?).', 'R000404-002': 'La lista de Waalaxy no existe.', 'R000401-003': 'La URL de LinkedIn no es válida para Waalaxy.', 'R000401-004': 'Se alcanzó el límite de prospectos de la lista o del CRM de Waalaxy.' })[code] || (res && res.statusCode === 429 ? 'Waalaxy limitó las llamadas (429): reintenta más tarde.' : 'Waalaxy no aceptó el alta.');
    state = 'error'; next = 'Revisar el error de Waalaxy y reintentar'; note = 'LINKEDIN · error al insertar en Waalaxy: ' + hint + ' (' + String(code || (res && res.statusCode) || 'sin respuesta').slice(0, 60) + ').'; msg = hint;
    events.push({ at: now, event: 'error_waalaxy', note: String(code || (res && res.statusCode) || '').slice(0, 80) });
  } else if (importCode === 'success' || importCode === 'duplicated_prospect' || importCode === 'prospect_successfully_moved_to_another_list') {
    ok = true;
    const inCamp = Boolean(wx.campaign_id) && (campCode === 'success' || campCode === 'already_in_campaign');
    state = inCamp ? 'en_campana' : 'en_lista';
    next = inCamp ? 'Waalaxy enviará la invitación; registrar «conexión aceptada» o «respondió» cuando ocurra' : 'En lista de Waalaxy sin campaña: no se contactó a nadie';
    note = 'LINKEDIN · ' + (inCamp ? 'alta en campaña de Waalaxy (la invitación de conexión la envía Waalaxy).' : 'agregado a la lista de Waalaxy SIN campaña (no se envió invitación ni mensaje).') + ' Persona: ' + wx.person + ' (' + wx.role + '). Resultado: ' + importCode + (campCode ? ' / campaña: ' + campCode : '') + '. Aprobado por ' + wx.by + '.';
    msg = (importCode === 'duplicated_prospect' ? 'Ya existía en Waalaxy (duplicado, no se creó otro). ' : 'Insertado en Waalaxy. ') + (inCamp ? 'Quedó en campaña.' : 'Quedó solo en la lista (sin campaña).');
    events.push({ at: now, event: inCamp ? 'alta_campana' : 'alta_lista', note: importCode + (campCode ? '/' + campCode : '') });
  } else {
    state = 'error'; next = 'Revisar el código de Waalaxy: ' + importCode; note = 'LINKEDIN · Waalaxy respondió «' + importCode + '»' + (item && item.message ? ': ' + String(item.message).slice(0, 120) : '') + '. No quedó en campaña.'; msg = 'Waalaxy respondió ' + importCode + '.';
    events.push({ at: now, event: 'import_' + importCode, note: String(item && item.message || '').slice(0, 80) });
  }
  const li = { ...prev, url: wx.url, person: wx.person, role: wx.role, state, list_id: wx.list_id, campaign_id: wx.campaign_id || null, waalaxy_prospect_id: pid || prev.waalaxy_prospect_id || null, import_code: importCode, campaign_code: campCode, mode_at_import: wx.mode,
    imported_at: ok ? now : prev.imported_at || null, last_event: events[events.length - 1].event, last_event_at: now, next_action: next, approved_by: wx.by, approved_at: now, confirm: null, events };
  const channel_state = { ...st, approved_channel: ok ? 'linkedin' : st.approved_channel || null, approved_at: ok ? now : st.approved_at || null, linkedin: li };
  const body = { channel_state, updated_at: now };
  const effects = [];
  if (state === 'en_campana' && wx.mode === 'live') { body.last_contact_channel = 'linkedin'; body.last_contact_at = now; effects.push({ type: 'gateway_act', act: { type: 'mark_contacted', channel: 'linkedin', note, follow_up_days: 5, at: now } }); }
  else if (state === 'en_campana') effects.push({ type: 'gateway_act', act: { type: 'mark_contacted', channel: 'linkedin', note: '[PRUEBA] ' + note, follow_up_days: 5, at: now } });
  else effects.push({ type: 'gateway_act', act: { type: 'add_note', note } });
  return { writes: [{ method: 'PATCH', path: 'prospect_candidates?id=eq.' + cand.id, body }], effects, state, ok, message: msg, import_code: importCode, campaign_code: campCode, waalaxy_prospect_id: pid };
}

function findCandidate(cands, target) {
  const t = String(target == null ? '' : target).trim();
  if (!t) return { error: 'falta_target' };
  const norm = (s) => liStrip(String(s || '')).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const list = Array.isArray(cands) ? cands : [];
  let m = list.filter((c) => c.id === t);
  if (!m.length) { const li = normLinkedInUrl(t); if (li) m = list.filter((c) => normLinkedInUrl(((c.canonical || {}).contact || {}).linkedin) === li); }
  if (!m.length && /\./.test(t) && !/\s/.test(t)) { const d = t.toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, ''); m = list.filter((c) => String(c.domain || '').toLowerCase() === d); }
  if (!m.length) { const n = norm(t); m = list.filter((c) => norm(c.company_name) === n); if (!m.length && n.length >= 3) m = list.filter((c) => norm(c.company_name).includes(n)); }
  if (m.length === 1) return { cand: m[0] };
  if (!m.length) return { error: 'sin_coincidencia' };
  return { error: 'ambiguo', options: m.slice(0, 6).map((c) => c.company_name) };
}

function isNamedPerson(name) {
  const n = String(name == null ? '' : name).replace(/\s+/g, ' ').trim();
  if (n.length < 5) return false;
  if (/no encontrad|desconocid|\bequipo\b|contacto|atenci[oó]n|soporte|ventas|comercial|administraci|servicio|capacitaci|info\b|\binc\b|ltda|\bspa\b/i.test(liStrip(n))) return false;
  const words = n.split(' ').filter((w) => /^[A-Za-zÁÉÍÓÚÜÑáéíóúüñ.'-]{2,}$/.test(w));
  return words.length >= 2;
}

function isReliableRole(role) {
  const r = String(role == null ? '' : role).trim();
  return r.length >= 3 && !/no encontrad|inferencia|probable|posible|\?/i.test(r);
}

function liConfirmHash(parts) { let h = 0x811c9dc5; const s = parts.join('\u0001'); for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }

function liLabel(state) { return ({ recomendado: 'Recomendado', aprobacion_pendiente: 'Pendiente de aprobación', en_lista: 'En lista (sin contactar)', en_campana: 'En campaña (conexión)', conexion: 'Conexión aceptada', mensaje: 'Mensaje enviado', followup: 'Follow-up enviado', respondio: 'Respondió', rechazo: 'Rechazó', detenido: 'Detenido', error: 'Error' })[state] || String(state || '—'); }

function liState(cand) { const s = (cand && cand.channel_state) || {}; return s.linkedin || null; }

function liStrip(s) { return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, ''); }

function linkedinOverview(cands, nowMs) {
  const list = Array.isArray(cands) ? cands : [];
  const counts = { pendiente: 0, en_lista: 0, en_campana: 0, conexion: 0, mensaje: 0, followup: 0, respondio: 0, rechazo: 0, error: 0 };
  const rows = [];
  let ready = 0;
  list.forEach((c) => {
    const v = linkedinView(c);
    const s = v.state;
    if (s === 'aprobacion_pendiente') counts.pendiente++;
    else if (counts[s] != null) counts[s]++;
    if (!s && v.recommended === 'linkedin') ready++;
    if (s || v.recommended === 'linkedin') rows.push(v);
  });
  rows.sort((a, b) => (Date.parse(b.last_event_at || 0) || 0) - (Date.parse(a.last_event_at || 0) || 0) || (b.score || 0) - (a.score || 0));
  return { counts, ready_for_linkedin: ready, rows: rows.slice(0, 12), total: rows.length };
}

function linkedinView(cand) {
  const st = (cand && cand.channel_state) || {};
  const rec = st.recommended || null;
  const li = st.linkedin || null;
  return { id: cand.id, company: cand.company_name, score: cand.priority_score, band: cand.band, recommended: rec ? rec.channel : null, reason: rec ? rec.reason : null, confidence: rec ? rec.confidence : null,
    approved_channel: st.approved_channel || null, state: li ? li.state : null, state_label: li ? liLabel(li.state) : null, person: li ? li.person : (rec ? rec.person : null), role: li ? li.role : (rec ? rec.role : null),
    url: li ? li.url : (rec ? rec.linkedin_url : null), list_id: li ? li.list_id : null, campaign_id: li ? li.campaign_id : null, last_event: li ? li.last_event : null, last_event_at: li ? li.last_event_at : null, next_action: li ? li.next_action : null,
    reply: li && li.reply ? li.reply : null, import_code: li ? li.import_code : null, campaign_code: li ? li.campaign_code : null };
}

function normLinkedInUrl(u) {
  const raw = String(u == null ? '' : u).trim();
  if (!raw) return null;
  const m = raw.match(/^(?:https?:\/\/)?(?:[a-z]{2,3}\.|www\.)?linkedin\.com\/in\/([A-Za-z0-9%_\-.]{3,100})\/?(?:[?#].*)?$/i);
  if (!m) return null;
  const slug = m[1].replace(/\/+$/, '');
  if (/^(company|school|sales|pub|feed|jobs)$/i.test(slug)) return null;
  return 'https://www.linkedin.com/in/' + slug.toLowerCase();
}

function planLinkedinApprove(req, ctx) {
  const nowMs = ctx.now, now = new Date(nowMs).toISOString();
  const cand = ctx.candidate, cfg = ctx.config || {};
  const fail = (error, message, status) => ({ response: { ok: false, status: status || 'error', error, message, executed: false, safety: { linkedin_invites_sent: 0 } }, writes: [], effects: [] });
  if (!cand) return fail('sin_candidato', 'No encontré ese prospecto.');
  if (cand.status === 'discarded') return fail('descartado', 'El prospecto está descartado.');
  const mode = cfg.linkedin_mode || 'off';
  const st = cand.channel_state || {};
  const prev = st.linkedin || null;
  if (prev && ['en_lista', 'en_campana', 'conexion', 'mensaje', 'followup', 'respondio'].includes(prev.state)) return fail('ya_en_linkedin', 'Ese prospecto ya está en LinkedIn (' + liLabel(prev.state) + '). No se vuelve a insertar.', 'already_done');
  if (ctx.emailActive) return fail('canal_email_activo', 'Ya hay un correo aprobado, en envío o enviado a este prospecto: no se contacta por LinkedIn al mismo tiempo (decisión explícita futura).', 'channel_conflict');
  const rec = recommendChannel(cand, { suppressedEmails: ctx.suppressedEmails });
  const c = (cand.canonical && cand.canonical.contact) || {};
  const url = normLinkedInUrl(c.linkedin || c.linkedin_url);
  if (!rec.linkedin_ready) return fail('linkedin_no_listo', 'Todavía no hay datos suficientes para LinkedIn: falta ' + (rec.missing.join(', ') || 'un perfil verificable') + '.', 'not_ready');
  const testMode = mode === 'test';
  const listId = testMode ? cfg.linkedin_test_list_id : cfg.linkedin_list_id;
  const campaignId = testMode ? null : (cfg.linkedin_campaign_id || null);
  if (testMode && !(cfg.linkedin_test_allowlist || []).includes(url)) return fail('fuera_de_allowlist', 'Modo test: solo se pueden insertar los perfiles de la lista blanca de prueba; este no está.', 'not_allowlisted');
  const person = String(c.name).trim(), role = String(c.role || c.job_title).trim();
  const body = { prospects: [{ url, customProfile: { ...(splitName(person).first ? { firstName: splitName(person).first } : {}), ...(splitName(person).last ? { lastName: splitName(person).last } : {}), occupation: role.slice(0, 120), company: { name: String(cand.company_name).slice(0, 120), ...(cand.website ? { website: cand.website } : {}) } }, customVariables: [{ label: 'Atacama_ref', value: String(cand.id) }] }],
    ...(listId ? { prospectListId: listId } : {}), ...(campaignId ? { campaignId } : {}), canCreateDuplicates: false, moveDuplicatesToOtherList: false, origin: { name: 'n8n' } };
  const hash = liConfirmHash([url, person, role, listId || '', campaignId || '', mode]);
  const summary = { company: cand.company_name, person, role, linkedin_url: url, list_id: listId || null, campaign_id: campaignId, mode, will_contact: Boolean(campaignId), what_happens: campaignId ? 'Se agrega a la lista y se inscribe en la campaña de Waalaxy: Waalaxy enviará la invitación de conexión según su configuración.' : 'Solo se agrega a la lista de Waalaxy (sin campaña): NO se envía ninguna invitación ni mensaje.' };
  const code = String(req.confirmation_code || '').trim();
  if (!code) {
    if (mode === 'off') return { response: { ok: false, status: 'mode_off', error: 'linkedin_apagado', executed: false, safety: { linkedin_invites_sent: 0 }, summary, message: 'LinkedIn está APAGADO (linkedin_mode=off): puedo mostrarte qué se haría, pero no se inserta nada hasta que Christian lo encienda.' }, writes: [], effects: [] };
    if (!listId) return fail('sin_lista', 'No hay lista de Waalaxy configurada para el modo ' + mode + '.', 'not_configured');
    const rnd = ctx.rnd || Math.random;
    const confirmCode = 'LI-' + (100000 + Math.floor(rnd() * 900000));
    const exp = new Date(nowMs + 30 * 60000).toISOString();
    const patch = { ...st, linkedin: { ...(prev || {}), url, person, role, state: 'aprobacion_pendiente', confirm: { code: confirmCode, hash, expires_at: exp }, last_event: 'aprobacion_solicitada', last_event_at: now, next_action: 'Christian confirma el alta en Waalaxy' } };
    return { response: { ok: false, status: 'confirmation_required', confirmation_code: confirmCode, expires_at: exp, executed: false, safety: { linkedin_invites_sent: 0 }, summary, message: 'Falta la confirmación de Christian. Muéstrale EXACTAMENTE este alta (persona, cargo, perfil, lista y campaña) y pídele que confirme. Si confirma, vuelve a llamar con confirmation_code y sus palabras en christian_order.' },
      writes: [{ method: 'PATCH', path: 'prospect_candidates?id=eq.' + cand.id, body: { channel_state: patch, updated_at: now } }], effects: [] };
  }
  const conf = prev && prev.confirm;
  if (!conf || conf.code !== code) return fail('codigo_invalido', 'El código no corresponde a este alta. Pide uno nuevo (llama sin código).', 'invalid_code');
  if (Date.parse(conf.expires_at) < nowMs) return fail('codigo_vencido', 'El código venció (30 min). Pide uno nuevo y confirma de nuevo.', 'expired_code');
  if (conf.hash !== hash) return fail('contenido_cambio', 'Los datos cambiaron después de emitir el código: Christian debe confirmar la versión actual.', 'content_changed');
  const order = String(req.order_text || '').trim();
  if (order.length < 4) return fail('falta_orden', 'Falta christian_order: las palabras exactas con las que Christian confirmó el alta.', 'needs_explicit_order');
  if (mode === 'off') return fail('linkedin_apagado', 'LinkedIn está APAGADO: no se inserta nada.', 'mode_off');
  if (mode === 'live' && Number(ctx.importedToday || 0) >= Number(cfg.linkedin_daily_cap || 0)) return fail('tope_diario', 'Se alcanzó el tope diario de altas a LinkedIn (' + cfg.linkedin_daily_cap + '). Mañana.', 'daily_cap');
  return { response: { ok: true, status: 'approved_pending_import', executed: false, safety: { linkedin_invites_sent: 0 }, summary, message: 'Aprobado: se inserta en Waalaxy ahora.' }, writes: [], effects: [],
    waalaxy: { body, order_text: order.slice(0, 400), by: req.by || 'Christian vía Hermes', url, person, role, list_id: listId, campaign_id: campaignId, mode } };
}

function planLinkedinEvent(req, ctx) {
  const nowMs = ctx.now, now = new Date(nowMs).toISOString();
  const cand = ctx.candidate;
  const fail = (error, message) => ({ response: { ok: false, status: 'error', error, message }, writes: [], effects: [] });
  if (!cand) return fail('sin_candidato', 'No encontré ese prospecto.');
  const st = cand.channel_state || {};
  const prev = st.linkedin;
  if (!prev || !['en_lista', 'en_campana', 'conexion', 'mensaje', 'followup', 'respondio', 'rechazo', 'detenido', 'error'].includes(prev.state)) return fail('no_esta_en_linkedin', 'Ese prospecto no fue dado de alta en LinkedIn por Atacama OS.');
  const ev = String(req.event || '').toLowerCase();
  const map = { conexion_aceptada: ['conexion', 'Conexión aceptada'], mensaje_enviado: ['mensaje', 'Mensaje enviado por la secuencia'], followup_enviado: ['followup', 'Follow-up enviado por la secuencia'], respondio: ['respondio', 'Respondió'], rechazo: ['rechazo', 'Rechazó / no le interesa'], detener: ['detenido', 'Secuencia detenida'], nota: [prev.state, 'Nota'] };
  if (!map[ev]) return fail('evento_invalido', 'Evento inválido. Usa: ' + Object.keys(map).join(', ') + '.');
  const text = String(req.note || req.text || '').trim().slice(0, 600);
  if (ev === 'respondio' && text.length < 2) return fail('falta_texto', 'Para registrar una respuesta indica qué dijo la persona (note).');
  const order = ['en_lista', 'en_campana', 'conexion', 'mensaje', 'followup', 'respondio'];
  const newState = map[ev][0];
  if (['conexion', 'mensaje', 'followup'].includes(newState) && order.indexOf(prev.state) > order.indexOf(newState) && prev.state !== 'error') return fail('retroceso', 'El prospecto ya está en «' + liLabel(prev.state) + '»: no se retrocede de estado.');
  const events = (prev.events || []).slice(-19); events.push({ at: now, event: ev, note: text.slice(0, 120) });
  const li = { ...prev, state: newState, last_event: ev, last_event_at: now, events,
    next_action: newState === 'respondio' ? 'Revisar la respuesta y decidir el siguiente paso (Diagnóstico)' : newState === 'rechazo' || newState === 'detenido' ? 'Ninguna: no volver a contactar por LinkedIn' : newState === 'conexion' ? 'Esperar el mensaje de la secuencia' : newState === 'mensaje' ? 'Esperar respuesta / follow-up de la secuencia' : newState === 'followup' ? 'Esperar respuesta; la secuencia termina sola' : prev.next_action,
    ...(newState === 'respondio' ? { reply: { text, at: now } } : {}), ...(ev === 'nota' ? { state: prev.state } : {}) };
  const body = { channel_state: { ...st, linkedin: li }, updated_at: now };
  const effects = [];
  const co = cand.company_name;
  if (newState === 'respondio') { body.status = 'contacted'; body.ghl_stage = 'respondio'; body.last_contact_channel = 'linkedin'; body.last_contact_at = now; body.next_action_at = null; effects.push({ type: 'gateway_act', act: { type: 'move_stage', stage: 'respondio', note: 'RESPUESTA por LinkedIn de ' + co + ' (' + (prev.person || '') + '): «' + text.slice(0, 500) + '». Se detienen los seguimientos de correo y de LinkedIn.' } }); }
  else if (newState === 'rechazo') { body.next_action_at = null; effects.push({ type: 'gateway_act', act: { type: 'move_stage', stage: 'respondio', note: 'RESPUESTA NEGATIVA por LinkedIn de ' + co + ': «' + text.slice(0, 300) + '». Seguimientos detenidos; decide si pasar a Perdida.' } }); }
  else if (newState === 'detenido') { body.next_action_at = null; effects.push({ type: 'gateway_act', act: { type: 'add_note', note: 'LINKEDIN · secuencia detenida. ' + text } }); }
  else effects.push({ type: 'gateway_act', act: { type: 'add_note', note: 'LINKEDIN · ' + map[ev][1] + (text ? ': ' + text : '') + '.' } });
  const stop = ['respondio', 'rechazo', 'detenido'].includes(newState);
  return { response: { ok: true, status: 'event_logged', company: co, state: li.state, state_label: liLabel(li.state), stop_followups: stop, message: 'Registrado en ' + co + ': ' + map[ev][1] + '.' + (stop ? ' Se detienen los seguimientos.' : '') }, writes: [{ method: 'PATCH', path: 'prospect_candidates?id=eq.' + cand.id, body }], effects, stop_email_followups: stop };
}

function planRecommend(req, ctx) {
  const now = new Date(ctx.now).toISOString();
  const cand = ctx.candidate;
  if (!cand) return { response: { ok: false, status: 'error', error: 'sin_candidato', message: 'No encontré ese prospecto.' }, writes: [], effects: [] };
  const rec = recommendChannel(cand, { suppressedEmails: ctx.suppressedEmails });
  const st = cand.channel_state || {};
  const nextRec = { channel: rec.channel, confidence: rec.confidence, reason: rec.reason, missing: rec.missing, email_ready: rec.email_ready, linkedin_ready: rec.linkedin_ready, linkedin_url: rec.linkedin_url, person: rec.person, role: rec.role, at: now };
  const patch = { ...st, recommended: nextRec };
  return { response: { ok: true, status: 'recommended', company: cand.company_name, recommendation: nextRec, current_state: st.linkedin ? st.linkedin.state : null, message: 'Canal recomendado para ' + cand.company_name + ': ' + (rec.channel === 'none' ? 'ninguno todavía (investigar más)' : rec.channel) + '. ' + rec.reason },
    writes: [{ method: 'PATCH', path: 'prospect_candidates?id=eq.' + cand.id, body: { channel_state: patch, updated_at: now } }], effects: [] };
}

function recommendChannel(cand, ctx) {
  const c = (cand && cand.canonical && cand.canonical.contact) || (cand && cand.contact) || {};
  const sup = (ctx && ctx.suppressedEmails) || [];
  const email = String(c.email || '').trim().toLowerCase();
  const emailOk = /^[^\s@<>()",;:]+@[^\s@<>()",;:]+\.[a-z]{2,}$/i.test(email) && c.public !== false && !sup.includes(email);
  const generic = /^(info|contacto|contact|ventas|comercial|hola|hello|admin|administracion|reservas|atencion|soporte|cotizaciones|cotizacion|sales|mail|oficina|clientes|secretaria|recepcion)@/i.test(liStrip(email));
  const li = normLinkedInUrl(c.linkedin || c.linkedin_url);
  const named = isNamedPerson(c.name);
  const role = isReliableRole(c.role || c.job_title);
  const evid = Boolean(String(c.linkedin_source_url || '').trim());
  const liReady = Boolean(li) && named && role && evid;
  const missing = [];
  if (!li) missing.push('URL de LinkedIn de una persona');
  if (!named) missing.push('nombre y apellido de la persona');
  if (!role) missing.push('cargo confiable');
  if (li && !evid) missing.push('evidencia pública de dónde salió el perfil');
  const out = (channel, confidence, reason, extra) => ({ channel, confidence, reason, missing: extra || [], email_ready: emailOk, linkedin_ready: liReady, linkedin_url: li, person: named ? String(c.name).trim() : null, role: role ? String(c.role || c.job_title).trim() : null });
  if (cand && (cand.status === 'discarded')) return out('none', 'alta', 'El prospecto está descartado.');
  const last = cand && cand.last_contact_channel;
  if (last && ['email', 'linkedin'].includes(last)) return out(last, 'alta', 'Ya se contactó por ' + last + ': no se abre un segundo canal sin una decisión explícita.');
  if (liReady && (!emailOk || generic)) return out('linkedin', emailOk ? 'media' : 'alta', 'Hay una persona identificada (' + String(c.name).trim() + ', ' + String(c.role || c.job_title).trim() + ') con perfil de LinkedIn verificable' + (emailOk ? ' y el único correo público es genérico (' + email + '): una persona con nombre tiene más probabilidad de respuesta.' : ' y no hay correo público utilizable.'));
  if (emailOk) return out('email', generic ? 'media' : 'alta', generic ? 'Correo público de la empresa (' + email + ', genérico): es el único canal confiable hoy' + (missing.length ? '; para LinkedIn falta ' + missing.join(', ') + '.' : '.') : 'Correo publicado por la empresa y utilizable (' + email + ').');
  if (liReady) return out('linkedin', 'media', 'Sin correo utilizable; hay persona con perfil de LinkedIn verificable.');
  return out('none', 'baja', 'Sin canal confiable: investigar más (' + (missing.join(', ') || 'falta un contacto público') + ').', missing);
}

function splitName(name) {
  const p = String(name || '').replace(/\s+/g, ' ').trim().split(' ');
  return { first: p[0] || '', last: p.slice(1).join(' ') };
}

function oaActionList() {
  return ['overview', 'email_save', 'email_approve', 'email_reject', 'email_reopen', 'linkedin_approve', 'linkedin_reject', 'content_approve', 'content_reject', 'autosend_set', 'autosend_sweep', 'prep_li_sent', 'prep_hold', 'prep_release', 'prep_contact'];
}

function oaAudit(req, R, final, nowMs) {
  const r = final.resp || {};
  const ent = {};
  if (req.message_id) { const m = (R.message || [])[0]; ent.message_id = req.message_id; if (m) { ent.company = m.company_name; ent.kind = m.kind; ent.to = m.to_email; } }
  if (req.candidate_id) { const c = (R.candidate || [])[0]; ent.candidate_id = req.candidate_id; if (c) ent.company = c.company_name; }
  if (req.piece_id) { const p = (R.piece || [])[0]; ent.piece_id = req.piece_id; if (p) { ent.topic = p.topic; ent.channel = p.channel; ent.ghl_post_id = p.ghl_post_id; } }
  const type = req.action.split('_')[0];
  const params = { type, decision: /approve/.test(req.action) ? 'approved' : /reject/.test(req.action) ? 'rejected' : req.action.replace(type + '_', ''), reason: req.reason || null, ...(req.subject ? { subject_len: req.subject.length, body_len: req.body.length } : {}) };
  return { request_id: req.request_id + (r.ok ? '' : '~' + Math.floor(nowMs / 1000).toString(36)), actor: 'Christian via /ops', tool: 'ops_' + req.action, level: /approve|autosend_set/.test(req.action) ? 3 : 2, entity: ent, params,
    status: r.ok ? 'executed' : 'refused', result_summary: String(r.message || '').slice(0, 300), response: { ok: Boolean(r.ok), status: r.status || null, error: r.error || null, message: String(r.message || '').slice(0, 300) } };
}

function oaCold(meta) {
  const c = meta && meta.cold;
  if (!c || typeof c.score !== 'number') return null;
  return { score: c.score, level: c.level || null, warnings: (c.warnings || []).slice(0, 6).map((w) => w.text), rewards: (c.rewards || []).slice(0, 6).map((r) => r.text), similarity: c.similarity || null, cta_kind: c.cta_kind || null, words: c.words || null,
    evidence: (c.evidence || []).slice(0, 4).map((e) => e.fact), insight: c.insight || null, friction: c.friction || null, angle: c.angle || null, cta_reason: c.cta_reason || null, linted_at: c.linted_at || null };
}

function oaDay(ms, tz) {
  return new Date(ms).toLocaleDateString('en-CA', { timeZone: tz || 'America/Santiago' });
}

function oaEmailCards(messages, cands, suppression) {
  const byId = {};
  (Array.isArray(cands) ? cands : []).forEach((c) => { byId[c.id] = c; });
  const sup = new Set((Array.isArray(suppression) ? suppression : []).map((s) => String((s && s.email) || '').toLowerCase()));
  return (Array.isArray(messages) ? messages : []).map((m) => {
    const c = byId[m.candidate_id] || {};
    const contact = c.contact || {};
    const st = m.status;
    return {
      id: m.id, candidate_id: m.candidate_id, kind: m.kind, company: m.company_name || c.company_name || '—',
      contact_name: contact.name || null, contact_role: contact.role || contact.job_title || null, to: m.to_email, subject: m.subject, body: m.body,
      status: st, editable: st === 'draft', can_reopen: st === 'approved', can_approve: st === 'draft', can_reject: st === 'draft' || st === 'approved',
      hash: m.content_hash || null, created_at: m.created_at, updated_at: m.updated_at, approved_at: m.approved_at || null, approved_by: m.approved_by || null,
      scheduled_for: m.scheduled_for || null, sent_at: m.sent_at || null, error: m.error || null,
      score: c.priority_score != null ? c.priority_score : null, band: c.band || null, reason: c.angle || null, evidence: c.quote || null,
      recommended_channel: ((c.channel_state || {}).recommended || {}).channel || null,
      suppressed: sup.has(String(m.to_email || '').toLowerCase()),
      rejected_reason: (m.metadata && m.metadata.rejected_reason) || null,
      cold: oaCold(m.metadata), previous: oaPrevious(m.metadata),
    };
  });
}

function oaIsUuid(v) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(v || ''));
}

function oaLinkedinData(cands, cfg, nowMs) {
  const tz = (cfg && cfg.tz) || 'America/Santiago';
  const today = oaDay(nowMs, tz);
  const ready = [], sent = [];
  const counts = { pendiente: 0, en_lista: 0, en_campana: 0, conexion: 0, mensaje: 0, followup: 0, respondio: 0, rechazo: 0, error: 0 };
  let importedToday = 0;
  (Array.isArray(cands) ? cands : []).forEach((c) => {
    const st = c.channel_state || {};
    const li = st.linkedin || null;
    const declined = (st.ops_declined || {}).linkedin || null;
    if (li && li.state) {
      if (li.state === 'aprobacion_pendiente') counts.pendiente++;
      else if (counts[li.state] != null) counts[li.state]++;
      if (['en_lista', 'en_campana', 'conexion', 'mensaje', 'followup', 'respondio', 'rechazo', 'detenido', 'error'].includes(li.state)) {
        if (li.imported_at && oaDay(Date.parse(li.imported_at), tz) === today && li.mode_at_import === 'live') importedToday++;
        sent.push({ candidate_id: c.id, company: c.company_name, person: li.person || null, role: li.role || null, url: li.url || null, approved_by: li.approved_by || null, approved_at: li.approved_at || null, imported_at: li.imported_at || null,
          list_id: li.list_id || null, campaign_id: li.campaign_id || null, score: c.priority_score != null ? c.priority_score : null, angle: c.angle || null, state: li.state, state_label: liLabel(li.state), last_event: li.last_event || null, last_event_at: li.last_event_at || null,
          import_code: li.import_code || null, campaign_code: li.campaign_code || null, mode_at_import: li.mode_at_import || null });
      }
      return;
    }
    if (declined) return;
    const rec = recommendChannel({ status: c.status, last_contact_channel: c.last_contact_channel, contact: c.contact || {} }, { suppressedEmails: [] });
    if (rec.channel === 'linkedin' && rec.linkedin_ready) {
      ready.push({ candidate_id: c.id, company: c.company_name, person: rec.person, role: rec.role, url: rec.linkedin_url, score: c.priority_score != null ? c.priority_score : null, band: c.band || null, angle: c.angle || null, fact: c.quote || null, reason: rec.reason,
        list_id: (cfg && cfg.linkedin_list_id) || null, campaign_id: (cfg && cfg.linkedin_campaign_id) || null, source: ((c.contact || {}).linkedin_source_url) || null });
    }
  });
  sent.sort((a, b) => (Date.parse(b.imported_at || b.approved_at || 0) || 0) - (Date.parse(a.imported_at || a.approved_at || 0) || 0));
  ready.sort((a, b) => (b.score || 0) - (a.score || 0));
  return { mode: (cfg && cfg.linkedin_mode) || 'off', cap: Number(cfg && cfg.linkedin_daily_cap) || 0, imported_today: importedToday, counts, ready, sent: sent.slice(0, 60) };
}

function oaOverview(R, nowMs) {
  const cfg = (R.config || [])[0] || {};
  const tz = cfg.tz || 'America/Santiago';
  const today = oaDay(nowMs, tz);
  const messages = R.messages || [];
  const emailToday = messages.filter((m) => m.status === 'sent' && m.sent_at && oaDay(Date.parse(m.sent_at), tz) === today).length;
  return { ok: true, action: 'overview', generated_at: new Date(nowMs).toISOString(), email: { mode: cfg.mode || 'off', paused: cfg.paused === true, cap: Number(cfg.daily_cap) || 0, sent_today: emailToday, window: (cfg.window_start || '09:00') + '–' + (cfg.window_end || '17:30'), cards: oaEmailCards(messages, R.candidates, R.suppression) },
    linkedin: oaLinkedinData(R.candidates, cfg, nowMs) };
}

function oaPrevious(meta) {
  const h = meta && Array.isArray(meta.history) ? meta.history : [];
  if (!h.length) return null;
  const p = h[h.length - 1];
  return { subject: p.subject || '', body: p.body || '', score: typeof p.score === 'number' ? p.score : null, at: p.at || null, by: p.by || null, reason: p.reason || null, versions: h.length };
}

function oaReads(req, sb) {
  const reads = [];
  const add = (key, path) => reads.push({ key, url: sb + path });
  if (req.request_id) add('audit', 'operator_audit_log?request_id=eq.' + req.request_id + '&select=status,response&limit=1');
  if (req.action === 'overview') {
    add('messages', 'outreach_messages?direction=eq.outbound&select=id,candidate_id,company_name,kind,to_email,subject,body,status,content_hash,created_at,updated_at,approved_by,approved_at,scheduled_for,sent_at,error,metadata&order=created_at.desc&limit=150');
    add('candidates', 'prospect_candidates?status=in.(in_ghl,accepted,contacted,discarded)&select=id,company_name,status,band,priority_score,ghl_stage,last_contact_channel,channel_state,domain,contact:canonical->contact,angle:canonical->>outreach_angle,quote:canonical->evidence_quotes->0->>quote&order=priority_score.desc&limit=400');
    add('suppression', 'outreach_suppression?select=email&limit=2000');
    add('config', 'outreach_config?id=eq.1&select=mode,paused,daily_cap,window_start,window_end,tz,linkedin_mode,linkedin_list_id,linkedin_campaign_id,linkedin_daily_cap');
  } else if (req.action.startsWith('email_')) {
    add('message', 'outreach_messages?id=eq.' + req.message_id + '&select=*,cand:prospect_candidates(id,company_name,status)&limit=1');
  } else if (req.action === 'autosend_set') {
    add('config', 'outreach_config?id=eq.1&select=autosend_enabled,autosend_min_score');
  } else if (req.action.startsWith('linkedin_') || req.action.startsWith('prep_')) {
    add('candidate', 'prospect_candidates?id=eq.' + req.candidate_id + '&select=id,company_name,status,channel_state,last_contact_channel,contact:canonical->contact&limit=1');
  } else if (req.action.startsWith('content_')) {
    add('piece', 'content_pieces?id=eq.' + req.piece_id + '&select=id,status,ghl_post_id,ghl_status,channel,format,topic,is_test,scheduled_at&limit=1');
  }
  return reads;
}

function oaRelay(r, fallback) {
  const b = r && r.body && typeof r.body === 'object' ? r.body : null;
  if (!r || !r.statusCode || r.statusCode >= 300 || !b) return { ok: false, error: 'sin_respuesta', message: fallback + ' (el motor no respondió' + (r && r.statusCode ? ': HTTP ' + r.statusCode : '') + ').' };
  return { ok: false, error: b.error || b.status || 'rechazado', message: String(b.message || fallback).slice(0, 400), engine_status: b.status || null };
}

function oaStep(req, R, results, nowMs, env) {
  const A = req.action;
  const nowIso = new Date(nowMs).toISOString();
  const by = 'Christian via /ops';
  const done = (resp, writes) => ({ final: { resp: { action: A, request_id: req.request_id, ...resp }, writes: writes || [] } });
  const fail = (error, message, extra) => done({ ok: false, error, message, ...(extra || {}) });
  const ingest = (path, body) => ({ call: { kind: 'ingest', method: 'POST', url: env.n8n + '/webhook/' + path, body } });
  const ghl = (method, path, body) => ({ call: { kind: 'ghl', method, url: 'https://services.leadconnectorhq.com/social-media-posting/' + env.ghl_loc + path, body: body || null } });
  const n = results.length;
  const ORDER = 'Aprobado desde /ops (sesión privada de Christian)';

  // ------------------------------------------------------------------ correo
  if (A.startsWith('email_')) {
    const m = (R.message || [])[0];
    if (!m) return fail('correo_no_encontrado', 'No encontré ese correo.');
    if (m.direction && m.direction !== 'outbound') return fail('no_es_saliente', 'Ese mensaje no es un correo saliente.');
    const label = (m.company_name || (m.cand && m.cand.company_name) || 'el prospecto');
    const st = m.status;
    if (A === 'email_reopen') {
      if (n === 0) {
        if (st === 'draft') return done({ ok: true, status: 'already_draft', message: 'Ya estaba como borrador.' });
        if (st !== 'approved') return fail('no_se_puede_reabrir', st === 'sending' || st === 'sent' ? 'Ese correo ya se está enviando o se envió: no se puede volver a borrador.' : 'Solo un correo aprobado que aún no sale se puede volver a borrador.', { current_status: st });
        return done({ ok: true, status: 'reopened', message: 'Volvió a borrador: la aprobación anterior quedó anulada. Edítalo y apruébalo de nuevo.' },
          [{ method: 'PATCH', path: 'outreach_messages?id=eq.' + m.id + '&status=eq.approved', body: { status: 'draft', approved_by: null, approved_at: null, approval_text: null, scheduled_for: null, confirm_code: null, confirm_hash: null, confirm_expires_at: null, updated_at: nowIso }, prefer: 'return=representation', check_rows: true, check_message: 'No pude volver a borrador: el correo ya no estaba aprobado (puede que ya haya empezado a enviarse).' }]);
      }
    }
    if (A === 'email_save') {
      if (n === 0) {
        if (st === 'approved') return fail('aprobado_no_editable', 'Ese correo está aprobado: usa «Volver a borrador» para editarlo (la aprobación anterior se anula).', { current_status: st });
        if (st !== 'draft') return fail('no_editable', st === 'sending' || st === 'sent' ? 'Ese correo ya se está enviando o se envió: no se puede editar.' : 'Ese correo está en estado «' + st + '» y no se puede editar.', { current_status: st });
        if (m.content_hash !== req.expected_hash) return fail('desactualizado', 'El correo cambió desde que lo abriste. Recarga para ver la versión actual.', { current_hash: m.content_hash });
        if (String(m.subject || '').trim() === req.subject && String(m.body || '').trim() === req.body) return done({ ok: true, status: 'unchanged', message: 'Sin cambios: el texto es el mismo.', hash: m.content_hash });
        return ingest('atacama-outreach-engine', { action: 'draft', candidate_id: m.candidate_id, kind: m.kind, subject: req.subject, body: req.body, by, reason: 'Editado desde /ops' });
      }
      const b = results[0] && results[0].body;
      if (b && b.ok && b.draft) return done({ ok: true, status: 'saved', message: 'Guardado. NO se envió: aprueba el envío cuando estés listo.', hash: b.draft.hash || null, draft: { subject: b.draft.subject, body: b.draft.body, status: b.draft.status } });
      return done(oaRelay(results[0], 'No pude guardar el borrador'));
    }
    if (A === 'email_approve') {
      if (n === 0) {
        if (st === 'approved') return done({ ok: true, status: 'already_approved', message: 'Ya estaba aprobado: sale en la próxima ventana de envío.' });
        if (st !== 'draft') return fail('no_aprobable', st === 'sending' || st === 'sent' ? 'Ese correo ya se está enviando o se envió.' : 'Ese correo está en estado «' + st + '» y no se puede aprobar.', { current_status: st });
        if (m.content_hash !== req.expected_hash) return fail('desactualizado', 'El correo cambió desde que lo abriste. Recarga y vuelve a leerlo antes de aprobar.', { current_hash: m.content_hash });
        return ingest('atacama-outreach-engine', { action: 'approve', candidate_id: m.candidate_id, kind: m.kind, by });
      }
      const b1 = results[0] && results[0].body;
      if (n === 1) {
        const shown = b1 && (b1.draft || b1.preview);
        if (b1 && b1.status === 'confirmation_required' && b1.confirmation_code) {
          if (shown && shown.hash && shown.hash !== req.expected_hash) return fail('desactualizado', 'La versión que el motor iba a aprobar no es la que viste. Recarga y vuelve a leer el correo.', { current_hash: shown.hash });
          return ingest('atacama-outreach-engine', { action: 'approve', candidate_id: m.candidate_id, kind: m.kind, confirmation_code: b1.confirmation_code, order_text: ORDER, by });
        }
        if (b1 && b1.status === 'already_approved') return done({ ok: true, status: 'already_approved', message: 'Ya estaba aprobado.' });
        return done(oaRelay(results[0], 'No pude aprobar el correo'));
      }
      const b2 = results[1] && results[1].body;
      if (b2 && b2.ok && b2.status === 'approved') return done({ ok: true, status: 'approved', message: 'Aprobado: ' + label + '. Saldrá cuando el envío lo permita (ventana lun–vie, tope diario). No se envió desde aquí.', scheduled_for: (b2.approved && b2.approved.scheduled_for) || b2.scheduled_for || null });
      return done(oaRelay(results[1], 'No pude aprobar el correo'));
    }
    if (A === 'email_reject') {
      if (n === 0) {
        if (!['draft', 'approved'].includes(st)) return fail('no_rechazable', st === 'sending' || st === 'sent' ? 'Ese correo ya se está enviando o se envió: no se puede rechazar.' : 'Ese correo está en estado «' + st + '».', { current_status: st });
        return ingest('atacama-outreach-engine', { action: 'cancel', candidate_id: m.candidate_id, kind: m.kind, by });
      }
      const b = results[0] && results[0].body;
      if (b && b.ok && b.status === 'cancelled') {
        const meta = { ...(m.metadata || {}), rejected_by: by, rejected_at: nowIso, rejected_reason: req.reason || null };
        return done({ ok: true, status: 'rejected', message: 'Rechazado: no se enviará. El borrador no se reactiva solo.' }, [{ method: 'PATCH', path: 'outreach_messages?id=eq.' + m.id, body: { metadata: meta, updated_at: nowIso } }]);
      }
      return done(oaRelay(results[0], 'No pude rechazar el correo'));
    }
  }

  // ---------------------------------------------------------------- LinkedIn
  if (A.startsWith('linkedin_')) {
    const c = (R.candidate || [])[0];
    if (!c) return fail('prospecto_no_encontrado', 'No encontré ese prospecto.');
    if (A === 'linkedin_reject') {
      const st = c.channel_state || {};
      const ops = { ...(st.ops_declined || {}), linkedin: { at: nowIso, by, reason: req.reason || null } };
      return done({ ok: true, status: 'rejected', message: 'Rechazado: no se propone de nuevo en /ops. No se contactó a nadie.' }, [{ method: 'PATCH', path: 'prospect_candidates?id=eq.' + c.id, body: { channel_state: { ...st, ops_declined: ops }, updated_at: nowIso } }]);
    }
    if (A === 'linkedin_approve') {
      if (n === 0) {
        const lis = (c.channel_state || {}).linkedin;
        if (lis && ['en_lista', 'en_campana', 'conexion', 'mensaje', 'followup', 'respondio'].includes(lis.state)) return fail('ya_en_linkedin', 'Ese prospecto ya está en LinkedIn.', { current_state: lis.state });
        return ingest('atacama-linkedin', { action: 'approve', target: c.id, by });
      }
      const b1 = results[0] && results[0].body;
      if (n === 1) {
        if (b1 && b1.status === 'confirmation_required' && b1.confirmation_code) return ingest('atacama-linkedin', { action: 'approve', target: c.id, confirmation_code: b1.confirmation_code, order_text: ORDER, by });
        return done(oaRelay(results[0], 'No pude aprobar el alta en LinkedIn'));
      }
      const b2 = results[1] && results[1].body;
      if (b2 && b2.ok && ['imported', 'approved_pending_import'].includes(b2.status)) return done({ ok: true, status: b2.status, message: 'Aprobado: ' + (c.company_name || '') + ' entró a la lista y a la campaña de Waalaxy. Waalaxy ejecuta la secuencia.', state: b2.state || null, state_label: b2.state_label || null });
      return done(oaRelay(results[1], 'No pude aprobar el alta en LinkedIn'));
    }
  }

  // ---------------------------------------------------------------- envío automático (interruptor): solo Christian, desde /ops
  if (A === 'autosend_set') {
    const cur = (R.config || [])[0] || {};
    const body = { autosend_enabled: req.enabled, autosend_updated_at: nowIso, autosend_updated_by: by, updated_at: nowIso };
    if (req.min_score != null) body.autosend_min_score = req.min_score;
    return done({ ok: true, status: req.enabled ? 'autosend_on' : 'autosend_off', enabled: req.enabled, min_score: req.min_score != null ? req.min_score : (Number(cur.autosend_min_score) || 80),
      message: req.enabled ? 'ENVÍO AUTOMÁTICO: ON. Los borradores elegibles (score ≥ ' + (req.min_score != null ? req.min_score : (Number(cur.autosend_min_score) || 80)) + ', correo directo publicado, no B/C, sin respuesta) se aprobarán solos y saldrán con el tope y la ventana de siempre. Puedes apagarlo cuando quieras.' : 'ENVÍO AUTOMÁTICO: OFF. Todo vuelve a quedar en Aprobaciones; lo que el autoenvío había aprobado y no salió vuelve a borrador.' },
      [{ method: 'PATCH', path: 'outreach_config?id=eq.1', body, prefer: 'return=representation', check_rows: true, check_message: 'No pude cambiar el interruptor.' }]);
  }
  if (A === 'autosend_sweep') {
    if (n === 0) return ingest('atacama-linkedin', { action: 'autosweep', by: 'Atacama OS · autoenvío (tras el interruptor)' });
    const b = results[0] && results[0].body;
    if (b && b.ok) return done({ ok: true, status: b.status, message: b.message, approved: b.approved || [], reverted: b.reverted || [], skipped_count: b.skipped_count || 0 });
    return done(oaRelay(results[0], 'No pude aplicar el barrido del autoenvío'));
  }

  // ---------------------------------------------------------------- contacto preparado (LinkedIn manual, espera, buscar contacto)
  if (A.startsWith('prep_')) {
    const c = (R.candidate || [])[0];
    if (!c) return fail('prospecto_no_encontrado', 'No encontré ese prospecto.');
    if (A === 'prep_li_sent') {
      if (n === 0) return ingest('atacama-linkedin', { action: 'li_sent', target: c.id, kind: req.kind, text: req.text, by });
      const bl = results[0] && results[0].body;
      if (bl && bl.ok) return done({ ok: true, status: bl.status, message: bl.message, follow_up_at: bl.follow_up_at || null, li_status: bl.li_status || null, ghl_stage: bl.ghl_stage || null, ghl_error: bl.ghl_error || null });
      return done(oaRelay(results[0], 'No pude registrar el envío por LinkedIn'));
    }
    if (A === 'prep_hold' || A === 'prep_release') {
      if (n === 0) return ingest('atacama-linkedin', { action: 'prep_set', target: c.id, state: A === 'prep_hold' ? 'hold' : 'clear', reason: req.reason, by });
