  if (action.startsWith('content_')) {
    if (!oaIsUuid(x.piece_id)) return { ok: false, error: 'piece_id_invalido', message: 'piece_id (uuid de la pieza) es obligatorio.' };
    req.piece_id = String(x.piece_id).toLowerCase();
  }
  return { ok: true, req };
}

