}

function oaEmailCards(messages, cands, suppression) {
  const byId = {};
  (Array.isArray(cands) ? cands : []).forEach((c) => { byId[c.id] = c; });
  const sup = new Set((Array.isArray(suppression) ? suppression : []).map((s) => String((s && s.email) || '').toLowerCase()));
